begin;
create extension if not exists pgtap with schema extensions;
select plan(17);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token) values('00000000-0000-0000-0000-000000000000','91000000-0000-4000-8000-000000000001','authenticated','authenticated','workflow@example.test','x',now(),'{}','{}',now(),now(),'','');
insert into public.companies(id,name,status) values('a1000000-0000-4000-8000-000000000001','Workflow A','active'),('a1000000-0000-4000-8000-000000000002','Workflow B','active');
insert into public.recruiter_profiles(id,company_id,user_id,display_name,email,role,status) values('b1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','Workflow','workflow@example.test','recruiter','active');
insert into public.demo_entitlements(company_id) values('a1000000-0000-4000-8000-000000000001'),('a1000000-0000-4000-8000-000000000002');
insert into public.job_roles(id,company_id,title,status) values('c1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Role A','open'),('c1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','Role B','open');
insert into public.job_requirements(id,company_id,job_id,label,description,priority,sort_order) values('d1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','Requirement','Requirement','required',1);
insert into public.candidates(id,company_id,name,source) values('e1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','Candidate A','manual'),('e1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','Candidate B','manual');
insert into public.candidate_applications(id,company_id,job_id,candidate_id,status,consent_status) values('f1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','processing','missing'),('f1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000002','processing','missing');
insert into public.uploaded_documents(id,company_id,application_id,candidate_id,file_name,storage_path,file_type,file_size_bytes,upload_status,parsing_status) values('11000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001','a.pdf','fixture/a.pdf','pdf',1,'accepted','queued'),('11000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000002','e1000000-0000-4000-8000-000000000002','b.pdf','fixture/b.pdf','pdf',1,'accepted','queued');

select set_config('request.jwt.claim.sub','91000000-0000-4000-8000-000000000001',true);
select public.start_current_pilot_lifecycle();
create temp table claims(n integer, value jsonb);
select is(has_function_privilege('authenticated','public.claim_document_analysis_run(uuid,uuid,text,text,jsonb)','EXECUTE'),false,'browser cannot claim a provider run');
select is(has_function_privilege('authenticated','public.finalize_document_analysis_run(uuid,uuid,uuid,jsonb)','EXECUTE'),false,'browser cannot forge report finalization');
select is(has_table_privilege('authenticated','public.document_analysis_runs','SELECT'),false,'extracted private text is not directly exposed');
insert into claims values(1,public.claim_document_analysis_run('11000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','[Page 1] Synthetic SQL reporting','browser_pdf_text','{"pageCount":1,"pageLabels":["Page 1"],"warnings":[]}'));
select is((select value->>'state' from claims where n=1),'claimed','first run claimed');
select is(public.claim_document_analysis_run('11000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','text','browser_pdf_text','{"pageCount":1}')->>'state','processing','concurrent request reuses active lease');
update public.document_analysis_runs set lease_expires_at=now()-interval '1 second' where document_id='11000000-0000-4000-8000-000000000001';
insert into claims values(2,public.claim_document_analysis_run('11000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','[Page 1] Synthetic SQL reporting','browser_pdf_text','{"pageCount":1,"pageLabels":["Page 1"],"warnings":[]}'));
select isnt((select value->>'lease_token' from claims where n=1),(select value->>'lease_token' from claims where n=2),'expired lease takeover rotates token');
select throws_ok($t$select public.finalize_document_analysis_run((select (value->>'run_id')::uuid from claims where n=1),'91000000-0000-4000-8000-000000000001',(select (value->>'lease_token')::uuid from claims where n=1),'{}')$t$,'P0001','ANALYSIS_RUN_NOT_FINALIZABLE','stale attempt cannot finish replacement');
select public.fail_document_analysis_run((select (value->>'run_id')::uuid from claims where n=1),'91000000-0000-4000-8000-000000000001',(select (value->>'lease_token')::uuid from claims where n=1),'STALE');
select is((select status from document_analysis_runs where document_id='11000000-0000-4000-8000-000000000001'),'processing','stale failure cannot cancel replacement');
select throws_ok($t$select public.claim_document_analysis_run('11000000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000001','text','browser_pdf_text','{"pageCount":1}')$t$,'P0001','DOCUMENT_NOT_IN_WORKSPACE','cross-company source denied');
select lives_ok($t$select public.finalize_document_analysis_run((select (value->>'run_id')::uuid from claims where n=2),'91000000-0000-4000-8000-000000000001',(select (value->>'lease_token')::uuid from claims where n=2),'{"requirementEvidence":[{"criteriaId":"d1000000-0000-4000-8000-000000000001","evidence":"Synthetic SQL reporting","sourceReference":"Page 1","confidence":"Medium","verificationNeeded":"Verify source","statusLabel":"Needs verification"}],"missingEvidence":[],"suggestedInterviewQuestions":[],"recruiterNotes":[]}')$t$,'validated model output persists atomically');
select is(public.claim_document_analysis_run('11000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','text','browser_pdf_text','{"pageCount":1}')->>'state','completed','completed repeat avoids new provider run');
select is((select count(*)::integer from evidence_reports where company_id='a1000000-0000-4000-8000-000000000001'),1,'exactly one report persisted');
select is((select source_reference from evidence_items where company_id='a1000000-0000-4000-8000-000000000001'),'Page 1','source reference retained');
select is((select status from evidence_reports where company_id='a1000000-0000-4000-8000-000000000001'),'Human review required','AI cannot finalize hiring outcome');
select is((select consent_status from candidate_applications where id='f1000000-0000-4000-8000-000000000001'),'missing','AI never implies candidate consent');
update public.demo_entitlements set activated_at=activated_at-interval '31 days', active_until=active_until-interval '31 days', purge_at=purge_at-interval '31 days' where company_id='a1000000-0000-4000-8000-000000000001';
select throws_ok($t$select public.claim_document_analysis_run('11000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','text','browser_pdf_text','{"pageCount":1}')$t$,'P0001','PILOT_EXPIRED','expired workspace blocked before provider');
update public.recruiter_profiles set status='disabled' where id='b1000000-0000-4000-8000-000000000001';
select throws_ok($t$select public.claim_document_analysis_run('11000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','text','browser_pdf_text','{"pageCount":1}')$t$,'42501','EXACTLY_ONE_ACTIVE_WORKSPACE_REQUIRED','disabled membership blocked');
select * from finish();
rollback;
